SELECT r.id, r.initial_integration_id, r.slack_channel_id, r.slack_thread_root_message_id, r.latest_status_job_id, r.status_source_job_id, r.slack_initiator_user_id, r.slack_agent_desired_status, r.slack_agent_observed_status, r.slack_session_observed_status, r.slack_publication_revision, r.slack_publication_sent_revision, r.slack_publication_claimed_revision, r.slack_publication_state, r.slack_publication_attempts, r.slack_publication_next_attempt_at, r.slack_publication_refresh_at, r.slack_publication_rate_limited_until, r.slack_publication_first_sent_at, r.slack_publication_last_sent_at, r.slack_publication_reason, r.slack_publication_warning, r.created_at, r.updated_at FROM slack_agent_session_publication r WHERE $criteria.CompositeIn("r", $WriterKeys)